from collections import deque,Counter

def comps(grid, target, bg=None):
 g=np.array(grid); seen=set(); out=[]
 for r in range(g.shape[0]):
  for c in range(g.shape[1]):
   if g[r,c]!=target or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for p in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=p[0]<g.shape[0] and 0<=p[1]<g.shape[1] and g[p]==target and p not in seen:seen.add(p);q.append(p)
   out.append(cells)
 return out
